message.content:
The bug is a **data race**:

```go
c.count++
```

`c.count++` is not atomic. Under heavy load, multiple goroutines can read the same value, increment it, and write it back, causing lost updates and a final count lower than `1000`.

Fix: protect `count` with a mutex.

<solution language="go" verdict="fix">
package main

import (
    "fmt"
    "sync"
)

type Counter struct {
    mu    sync.Mutex
    count int
}

func (c *Counter) Increment() {
    c.mu.Lock()
    defer c.mu.Unlock()
    c.count++
}

func (c *Counter) GetCount() int {
    c.mu.Lock()
    defer c.mu.Unlock()
    return c.count
}

func main() {
    counter := &Counter{}
    var wg sync.WaitGroup

    for i := 0; i < 1000; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            counter.Increment()
        }()
    }

    wg.Wait()
    fmt.Println("Final count:", counter.GetCount())
}
</solution>

